$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);if(!$id){http_response_code(404);exit('Order not found.');}$pdo=db();$q=$pdo->prepare('SELECT * FROM orders WHERE id=?');$q->execute([$id]);$o=$q->fetch();if(!$o){http_response_code(404);exit('Order not found.');}$error='';
