?><!doctype html><html lang="en" data-theme="dark"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($o['order_code'])?> — Hammad Graphic</title><link rel="stylesheet" href="../assets/css/style.css"></head><body class="admin-dashboard"><header class="admin-topbar"><a class="brand" href="../index.php"><span class="brand-mark">H<span>G</span></span><span class="brand-name">HAMMAD<span>GRAPHIC</span></span></a><div class="admin-user"><a href="index.php">All orders</a><form method="post" action="logout.php"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><button class="logout-button">Log out ↗</button></form></div></header><main class="admin-container"><div class="admin-title-row"><div><div class="eyebrow">CUSTOMER REQUEST</div><h1><?=e($o['order_code'])?></h1><p>Received <?=e(date('d M Y, H:i',strtotime($o['created_at'])))?></p></div><a class="button button-outline" href="index.php">← All orders</a></div><?php if(isset($_GET['saved'])): ?><div class="alert alert-success">Order updated successfully.</div><?php endif; ?><?php if($error): ?><div class="alert alert-error"><?=e($error)?></div><?php endif; ?><div class="order-detail-grid"><section class="admin-panel detail-panel"><div class="eyebrow">CUSTOMER BRIEF</div><h2><?=e($o['customer_name'])?></h2><dl class="detail-list"><div><dt>Email</dt><dd><a href="mailto:<?=e($o['email'])?>"><?=e($o['email'])?></a></dd></div><div><dt>WhatsApp</dt><dd><a href="https://wa.me/<?=e(preg_replace('/\D+/','',$o['whatsapp']))?>" target="_blank"><?=e($o['whatsapp'])?> ↗</a></dd></div><div><dt>Service</dt><dd><?=e($o['service'])?></dd></div><div><dt>Budget</dt><dd><?=e($o['budget']?:'Not provided')?></dd></div><div><dt>Deadline</dt><dd><?=e($o['deadline']?date('d M Y',strtotime($o['deadline'])):'Not specified')?></dd></div><div><dt>Attachment</dt><dd><?=$o['attachment']?'<a href="download.php?id='.(int)$o['id'].'">Download customer reference ↗</a>':'None'?></dd></div></dl><div class="brief-box"><span>PROJECT DESCRIPTION</span><p><?=nl2br(e($o['brief']))?></p></div></section><section class="admin-panel update-panel"><div class="eyebrow">MANAGE REQUEST</div><h2>Update order</h2><p><a class="table-action" href="quote.php?id=<?=(int)$o['id']?>">Set quote / verify payment ↗</a></p><form method="post" class="admin-form"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><label>Order status<select name="status"><?php foreach(['pending'=>'Pending review','confirmed'=>'Confirmed','in_progress'=>'In progress','completed'=>'Completed','cancelled'=>'Cancelled'] as $v=>$label): ?><option value="<?=e($v)?>" <?=$o['status']===$v?'selected':''?>><?=e($label)?></option><?php endforeach; ?></select></label><label>Private admin note<textarea name="admin_note" rows="7" maxlength="5000"><?=e($o['admin_note']??'')?></textarea><small>Only visible in this admin panel.</small></label><button class="button button-primary">Save update ↗</button></form><div class="whatsapp-reminder"><strong>Confirm with the customer</strong><p>Status changes do not automatically send an alert. Contact the customer directly.</p><a href="https://wa.me/<?=e(preg_replace('/\D+/','',$o['whatsapp']))?>?text=<?=rawurlencode('Hello '.$o['customer_name'].', I am following up about your Hammad Graphic request '.$o['order_code'].'.')?>" target="_blank">Open WhatsApp ↗</a></div></section></div></main></body></html>